import {
  type blockClass,
  type CanvasArg,
  CanvasContext,
  type canvasManagerMutationCallback,
  type canvasMutationWithType,
  type IWindow,
  type listenerHandler,
  type DataURLOptions,
} from '@posthog/rrweb-types';
import { hookSetter, isBlocked } from '../../../utils';
import { patch } from '@posthog/rrweb-utils';
import { saveWebGLVar, serializeArgs } from './serialize-args';

function patchGLPrototype(
  prototype: WebGLRenderingContext | WebGL2RenderingContext,
  type: CanvasContext,
  cb: canvasManagerMutationCallback,
  blockClass: blockClass,
  blockSelector: string | null,
  win: IWindow,
  dataURLOptions: DataURLOptions,
): listenerHandler[] {
  const handlers: listenerHandler[] = [];

  const props = Object.getOwnPropertyNames(prototype);

  for (const prop of props) {
    if (
      //prop.startsWith('get') ||  // e.g. getProgramParameter, but too risky
      [
        'isContextLost',
        'canvas',
        'drawingBufferWidth',
        'drawingBufferHeight',
      ].includes(prop)
    ) {
      // skip read only propery/functions
      continue;
    }
    try {
      if (typeof prototype[prop as keyof typeof prototype] !== 'function') {
        continue;
      }
      const restoreHandler = patch(
        prototype,
        prop,
        function (
          original: (this: typeof prototype, ...args: Array<unknown>) => void,
        ) {
          return function (this: typeof prototype, ...args: Array<unknown>) {
            const result = original.apply(this, args);
            saveWebGLVar(result, win, this);
            if (
              !!this.canvas &&
              'tagName' in this.canvas &&
              !isBlocked(this.canvas, blockClass, blockSelector, true)
            ) {
              let recordArgs: CanvasArg[] | undefined;
              try {
                recordArgs = serializeArgs(args, win, this, dataURLOptions);
              } catch {
                // this runs inside the page's own call, so an argument such as
                // a tainted canvas must not throw into it. Skip the mutation
              }
              if (recordArgs) {
                const mutation: canvasMutationWithType = {
                  type,
                  property: prop,
                  args: recordArgs,
                };
                // TODO: this could potentially also be an OffscreenCanvas as well as HTMLCanvasElement
                cb(this.canvas, mutation);
              }
            }

            return result;
          };
        },
      );
      handlers.push(restoreHandler);
    } catch {
      const hookHandler = hookSetter<typeof prototype>(prototype, prop, {
        set(v) {
          if (
            !!this.canvas &&
            'tagName' in this.canvas &&
            !isBlocked(this.canvas, blockClass, blockSelector, true)
          ) {
            cb(this.canvas, {
              type,
              property: prop,
              args: [v],
              setter: true,
            });
          }
        },
      });
      handlers.push(hookHandler);
    }
  }

  return handlers;
}

export default function initCanvasWebGLMutationObserver(
  cb: canvasManagerMutationCallback,
  win: IWindow,
  blockClass: blockClass,
  blockSelector: string | null,
  dataURLOptions: DataURLOptions,
): listenerHandler {
  const handlers: listenerHandler[] = [];

  if (typeof win.WebGLRenderingContext !== 'undefined') {
    handlers.push(
      ...patchGLPrototype(
        win.WebGLRenderingContext.prototype,
        CanvasContext.WebGL,
        cb,
        blockClass,
        blockSelector,
        win,
        dataURLOptions,
      ),
    );
  }

  if (typeof win.WebGL2RenderingContext !== 'undefined') {
    handlers.push(
      ...patchGLPrototype(
        win.WebGL2RenderingContext.prototype,
        CanvasContext.WebGL2,
        cb,
        blockClass,
        blockSelector,
        win,
        dataURLOptions,
      ),
    );
  }

  return () => {
    handlers.forEach((h) => h());
  };
}
